const newItems = items.map(item => {
  const json = item.json;
  const caption = json.message.caption || "";

  // Split lines and clean
  const lines = caption.split('\n').map(l => l.trim()).filter(l => l !== '');

  // Line 0 = price
  let rawPriceLine = lines[0] || "0";
  let priceMatch = rawPriceLine.match(/(\d+[\.,]?\d*)/);
  let cleanPrice = priceMatch ? parseFloat(priceMatch[0]) : 0;

  // Line 1 = product name
  let productName = lines[1] || "منتج غير محدد";

  // Line 2 = SKU/Ref
  let productSku = lines[2] || lines[1] || "غير محدد";

  // Chat ID for sending the reply
  const chatId = json.message.chat.id;
  const messageId = json.message.message_id;

  return {
    json: {
      ...json,
      extracted_price: cleanPrice,
      extracted_name: productName,
      extracted_sku: productSku,
      chat_id: chatId,
      message_id: messageId
    }
  };
});

return newItems;

